package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AssigneeNameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property assignee name of observed issue ")
  void test_assignee_name_v_o_builder() {
    Assertions.assertFalse(AssigneeNameVO.nullValue().getAssigneeName().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(AssigneeNameVO.tryFrom(null).getAssigneeName().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", AssigneeNameVO.from("one").getAssigneeName().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AssigneeNameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AssigneeNameVO.from("one").toString());
  }
}
